const state = $getWorkflowStaticData('global');
if (!state.issues) state.issues = {};
if (!state.lqa) state.lqa = {};
if (!state.versions) state.versions = {};
const firstRun = !state.seeded;
const lqaFirstRun = !state.lqaSeeded;
const now = Date.now();
const LINK_TYPE_ID = '10079'; // "Has localization ticket"
const esc = function (s) { return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const base = 'https://futuremedia.atlassian.net/browse/';
const link = function (k) { return '<' + base + k + '|' + k + '>'; };
const sigOf = function (v) { return v.name + '|' + v.releaseDate + '|' + v.released; };
const parseSig = function (s) { const parts = s.split('|'); const released = parts.pop() === 'true'; const releaseDate = parts.pop() || ''; return { name: parts.join('|'), releaseDate: releaseDate, released: released }; };
const verLineOf = function (versions) { if (!versions) return 'unknown'; return versions.length ? versions.map(function (v) { return esc(v.name) + ' (' + (v.releaseDate || 'no date') + (v.released ? ', released' : ', not released') + ')'; }).join(', ') : 'none'; };
const buildText = function (key, summary, changes, verLine, llrLine) {
  return ':bell: *' + link(key) + '* – ' + esc(summary) + '\n' + changes.join('\n') + '\nFix version: ' + verLine + '\nLocalization ticket: ' + llrLine;
};

const productIssues = (($('Fetch localized product tickets').first().json || {}).issues) || [];
let llrIssues = [];
try { llrIssues = ($input.first().json.issues) || []; } catch (e) { llrIssues = []; }
const llrByKey = {};
for (const l of llrIssues) llrByKey[l.key] = l;

// 1) LQA status changes on localization (INTERNAT) tickets
const lqaChanges = {}; // product key -> { lines, llrKeys, issue }
for (const l of llrIssues) {
  const f = l.fields || {};
  const val = f.customfield_11581 ? f.customfield_11581.value : '';
  const prev = state.lqa[l.key];
  state.lqa[l.key] = { value: val, seen: now };
  if (lqaFirstRun) continue;
  let changed = false;
  let fromTxt = '';
  // An LL ticket seen for the first time is only recorded, never reported
  if (prev && prev.value !== val) { changed = true; fromTxt = prev.value || 'not set'; }
  if (!changed) continue;
  const products = (f.issuelinks || []).filter(function (x) { return x.type && x.type.id === LINK_TYPE_ID && x.inwardIssue; }).map(function (x) { return x.inwardIssue; });
  for (const p of products) {
    if (!lqaChanges[p.key]) lqaChanges[p.key] = { lines: [], llrKeys: [], issue: p };
    lqaChanges[p.key].lines.push(':mag: LQA status (' + l.key + '): ' + esc(fromTxt) + ' → ' + '*' + esc(val || 'not set') + '*');
    lqaChanges[p.key].llrKeys.push(l.key);
  }
}

const out = [];
const groups = {}; // version-level events, one message per version + event
const groupOrder = [];
// 2) Product tickets: ticket-level changes go per ticket, version-level events are grouped per version
for (const it of productIssues) {
  const f = it.fields || {};
  const llrs = (f.issuelinks || []).filter(function (l) { return l.type && l.type.id === LINK_TYPE_ID && l.outwardIssue; }).map(function (l) { return l.outwardIssue; });
  if (!llrs.length) continue;
  const status = f.status ? f.status.name : '';
  const versions = (f.fixVersions || []).map(function (v) { return { id: v.id, name: v.name, releaseDate: v.releaseDate || '', released: !!v.released }; });
  const verSig = versions.map(sigOf).sort().join(';');
  const prev = state.issues[it.key];
  state.issues[it.key] = { status: status, verSig: verSig, seen: now, threadTs: prev && prev.threadTs ? prev.threadTs : '', summary: f.summary || '', llrKeys: llrs.map(function (l) { return l.key; }) };
  const lqa = lqaChanges[it.key];
  delete lqaChanges[it.key];
  const llrLine = llrs.map(function (l) { const st = l.fields && l.fields.status ? l.fields.status.name : ''; return link(l.key) + (st ? ' (' + esc(st) + ')' : ''); }).join(', ');
  const changes = [];
  if (!firstRun && prev) {
    if (prev.status !== null && prev.status !== undefined && prev.status !== status) {
      const prodNote = status === 'QA PROD' ? ' :rocket: _deployed to prod_' : '';
      changes.push('Status: ' + esc(prev.status) + ' → *' + esc(status) + '*' + prodNote);
    }
    if (prev.verSig !== null && prev.verSig !== undefined && prev.verSig !== verSig) {
      const prevVers = prev.verSig ? prev.verSig.split(';').map(parseSig) : [];
      for (const v of versions) {
        const p = prevVers.find(function (x) { return x.name === v.name; });
        let event = '';
        if (!p) changes.push('Fix version added: *' + esc(v.name) + '*' + (v.releaseDate ? ' (planned release ' + v.releaseDate + ')' : ''));
        else if (v.released && !p.released) event = ':rocket: *released*' + (v.releaseDate ? ' on *' + v.releaseDate + '*' : '');
        else if (!v.released && p.released) event = ':warning: release *reverted* (marked as not released again)';
        else if (p.releaseDate !== v.releaseDate) event = ':calendar: release date moved: ' + (p.releaseDate || 'not set') + ' → *' + (v.releaseDate || 'not set') + '*';
        if (event) {
          const gk = (v.id || v.name) + '#' + event;
          if (!groups[gk]) { groups[gk] = { versionId: v.id || v.name, version: v, project: it.key.split('-')[0], event: event, tickets: [], llrKeys: [] }; groupOrder.push(gk); }
          groups[gk].tickets.push('• ' + link(it.key) + ' – ' + esc(f.summary) + ' · ' + esc(status) + ' · LL: ' + llrLine);
          for (const l of llrs) if (groups[gk].llrKeys.indexOf(l.key) < 0) groups[gk].llrKeys.push(l.key);
        }
      }
      for (const p of prevVers) {
        if (!versions.find(function (v) { return v.name === p.name; })) changes.push('Fix version removed: *' + esc(p.name) + '*');
      }
    }
  }
  if (lqa) for (const line of lqa.lines) changes.push(line);
  if (!changes.length) continue;
  out.push({ json: { kind: 'ticket', groupKey: '', key: it.key, status: status, llrKeys: llrs.map(function (l) { return l.key; }), threadTs: state.issues[it.key].threadTs, changesText: changes.join('\n'), text: buildText(it.key, f.summary, changes, verLineOf(versions), llrLine) } });
}

// 3) One message per version event, listing every localized ticket in that version
for (const gk of groupOrder) {
  const g = groups[gk];
  const v = g.version;
  const vs = state.versions[g.versionId] || { threadTs: '' };
  vs.seen = now;
  state.versions[g.versionId] = vs;
  const header = ':package: *Version ' + esc(v.name) + '* (' + esc(g.project) + ') – ' + g.event;
  const body = 'Release: ' + (v.releaseDate || 'no date') + (v.released ? ', released' : ', not released') + '\nLocalized tickets (' + g.tickets.length + '):\n' + g.tickets.join('\n');
