  out.push({ json: { kind: 'ticket', groupKey: '', key: key, status: pf.status ? pf.status.name : (st.status || ''), llrKeys: llrKeys, threadTs: st.threadTs || '', changesText: c.lines.join('\n'), text: buildText(key, pf.summary || st.summary, c.lines, verLineOf(versions), llrLine) } });
