for (const k of Object.keys(state.issues)) if (old(state.issues[k])) delete state.issues[k];
for (const k of Object.keys(state.lqa)) if (old(state.lqa[k])) delete state.lqa[k];
for (const k of Object.keys(state.versions)) if (old(state.versions[k])) delete state.versions[k];
state.seeded = true;
state.lqaSeeded = true;
return out;

